<script lang="ts">
  import { navigate } from 'svelte-routing'
  import { getAddresses, getCart, getProducts, createOrder } from '../data/store'
  import type { Address, CartItem, Product } from '../types'
  let addresses = $state<Address[]>([]); let cart = $state<CartItem[]>([]); let products = $state<Product[]>([]); let addressId = $state(''); let payment = $state('Card'); let processing = $state(false); let error = $state('')
  let lines = $derived(cart.map((item) => ({ ...item, product: products.find((product) => product.id === item.productId) })).filter((line) => line.product)); let subtotal = $derived(lines.reduce((sum, line) => sum + line.product!.price * line.quantity, 0)); let shipping = $derived(subtotal > 75 ? 0 : 8); let total = $derived(subtotal + shipping); let selectedAddress = $derived(addresses.find((address) => address.id === addressId)); let isValid = $derived(Boolean(selectedAddress && cart.length && payment))
  $effect(() => { Promise.all([getAddresses(), getCart(), getProducts()]).then(([savedAddresses, savedCart, savedProducts]) => { addresses = savedAddresses; addressId = savedAddresses.find((address) => address.isDefault)?.id ?? savedAddresses[0]?.id ?? ''; cart = savedCart; products = savedProducts }) })
  async function pay(): Promise<void> { if (!isValid || !selectedAddress) return; processing = true; error = ''; try { const order = await createOrder({ items: cart, total, status: 'Processing', paymentStatus: 'Paid', address: selectedAddress }); navigate('/orders/' + order.id) } catch { error = 'Your payment could not be completed. Please try again.'; processing = false } }
</script>
<section class="mx-auto max-w-5xl"><div class="flex items-center justify-between"><div><p class="text-sm font-semibold text-primary">CHECKOUT</p><h1 class="mt-1 text-3xl font-bold text-navy">Complete your order</h1></div><button onclick={() => history.back()} class="text-sm font-semibold text-primary">Back to cart</button></div>{#if cart.length}<div class="mt-7 grid gap-6 lg:grid-cols-3"><div class="space-y-5 lg:col-span-2"><section class="rounded-panel bg-card p-5 ring-1 ring-line"><h2 class="font-bold text-navy">1. Delivery address</h2><div class="mt-4 space-y-3">{#each addresses as address (address.id)}<label class={addressId === address.id ? 'block cursor-pointer rounded-xl border-2 border-primary p-4' : 'block cursor-pointer rounded-xl border border-line p-4'}><input type="radio" bind:group={addressId} value={address.id} class="mr-2"/><span class="font-semibold text-navy">{address.label}</span><p class="ml-6 mt-1 text-sm text-muted">{address.recipient} · {address.line1}, {address.city}, {address.state} {address.postalCode}</p></label>{:else}<p class="text-sm text-muted">No address saved. Add one from My Account.</p>{/each}</div><button onclick={() => navigate('/account')} class="mt-4 text-sm font-semibold text-primary">Manage addresses</button></section><section class="rounded-panel bg-card p-5 ring-1 ring-line"><h2 class="font-bold text-navy">2. Payment method</h2><div class="mt-4 grid gap-3 sm:grid-cols-3">{#each ['Card','UPI','Net banking'] as method}<button onclick={() => payment = method} class={payment === method ? 'rounded-xl border-2 border-primary p-4 text-sm font-semibold text-primary' : 'rounded-xl border border-line p-4 text-sm font-semibold text-navy'}>{method}</button>{/each}</div><p class="mt-4 text-sm text-muted">Your selected payment method will be securely processed when you place the order.</p></section></div><aside class="h-fit rounded-panel bg-card p-5 ring-1 ring-line"><h2 class="font-bold text-navy">Order summary</h2>{#each lines as line (line.productId + line.color)}<p class="mt-4 flex justify-between text-sm"><span class="max-w-44 text-muted">{line.product!.name} × {line.quantity}</span><span>${(line.product!.price * line.quantity).toFixed(2)}</span></p>{/each}<p class="mt-4 flex justify-between text-sm"><span class="text-muted">Delivery</span><span>{shipping === 0 ? 'Free' : '$' + shipping}</span></p><p class="mt-4 flex justify-between border-t border-line pt-4 text-lg font-bold text-navy"><span>Total</span><span>${total.toFixed(2)}</span></p>{#if error}<p class="mt-3 rounded-lg bg-red-50 p-3 text-sm text-danger">{error}</p>{/if}<button disabled={!isValid || processing} onclick={pay} class="mt-6 w-full rounded-xl bg-primary px-4 py-3 font-semibold text-white disabled:opacity-50">{processing ? 'Processing payment…' : 'Pay $' + total.toFixed(2)}</button><p class="mt-3 text-center text-xs text-muted">Secure payment · Your order is protected</p></aside></div>{:else}<div class="mt-7 rounded-panel bg-card p-10 text-center text-muted">Your cart is empty. <button onclick={() => navigate('/products')} class="font-semibold text-primary">Start shopping</button></div>{/if}</section>
